int64_t nitems = (int64_t)(*FUZZ_PARAM(unsigned int) % 64);
int64_t position = (int64_t)(*FUZZ_PARAM(unsigned int) % 4096);

void *outptr = nullptr;
void **pptr = &outptr; // output parameter; do not free, backend owns while mapping is open

int64_t nread = blosc2_stdio_mmap_read(pptr, size, nitems, position, stream);
(void)nread;

// Keep stream alive

// Validate backend and open state
const char *kind = FUZZ_GET_ATTR_STR(stream, "io_kind");
int is_mmap = (kind && kind[0] != '\0' && !strcmp(kind, "mmap"));
int is_open = FUZZ_GET_ATTR_INT(stream, "open");
if (!is_mmap || !is_open) { FUZZ_BAIL(); }

int64_t newsize = (int64_t)(*FUZZ_PARAM(unsigned int) % 8192);
int rc = blosc2_stdio_mmap_truncate(stream, newsize);
(void)rc;

// Keep stream alive

// Create a configuration object and mark needs_free according to fuzz input
blosc2_stdio_mmap *params = new blosc2_stdio_mmap();
unsigned int v = *FUZZ_PARAM(unsigned int);
params->mode = "r"; // default; not used by destroy
params->initial_mapping_size = (int64_t)(v % 1024);
params->needs_free = ((v & 1) != 0);
params->addr = nullptr;
params->urlpath = nullptr;
params->file_size = 0;
params->mapping_size = 0;
params->is_memory_only = false;
params->file = nullptr;
params->fd = -1;
params->access_flags = 0;
params->map_flags = 0;
#if defined(_WIN32)
params->mmap_handle = 0;
#endif

int rc = blosc2_stdio_mmap_destroy((void*)params);
(void)rc;

