import random
from typing import List

# This generator produces arbitrary binary data tailored to exercise the Blosc2
# fuzz stubs that consume FUZZ_PARAM_STR() and FUZZ_PARAM_FILENAME().
# It focuses on valid, diverse byte patterns under 1024 bytes.


def _gen_runs(rng: random.Random, length: int) -> bytes:
    out = bytearray()
    while len(out) < length:
        run_len = rng.randint(1, max(1, min(64, length - len(out))))
        b = rng.randrange(0, 256)
        out.extend([b] * run_len)
    return bytes(out[:length])


def _gen_periodic(rng: random.Random, length: int) -> bytes:
    if length <= 0:
        return b""
    period = rng.choice([2, 3, 4, 5, 7, 8, 16, 32])
    motif = bytes(rng.randrange(0, 256) for _ in range(period))
    return (motif * (length // period + 1))[:length]


def _gen_ramps(rng: random.Random, length: int, typesize: int) -> bytes:
    if length <= 0:
        return b""
    max_items = max(1, length // max(1, typesize))
    out = bytearray()
    # limit seed to 32 bits to avoid huge ints
    val = rng.randrange(0, 1 << min(8 * typesize, 32))
    step = rng.randrange(1, 17)
    mask = (1 << (8 * max(1, typesize))) - 1 if typesize * 8 < 64 else (1 << 64) - 1
    for i in range(max_items):
        v = (val + i * step) & mask
        out.extend(int(v).to_bytes(max(1, typesize), 'little', signed=False))
        if len(out) >= length:
            break
    return bytes(out[:length]).ljust(length, b"\x00")


def _gen_prng(rng: random.Random, length: int) -> bytes:
    if length <= 0:
        return b""
    return bytes(rng.randrange(0, 256) for _ in range(length))


def _gen_ascii(rng: random.Random, length: int) -> bytes:
    if length <= 0:
        return b""
    alphabet = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-./"
    return bytes(alphabet[rng.randrange(0, len(alphabet))] for _ in range(length))


def _compose_segments(rng: random.Random, target_len: int) -> bytes:
    if target_len <= 0:
        return b""
    pieces: List[bytes] = []
    remaining = target_len
    while remaining > 0:
        hi = min(256, remaining)
        lo = 1 if hi < 16 else 16
        seg_len = rng.randint(lo, hi)
        kind = rng.choice(['runs', 'periodic', 'ramp2', 'ramp4', 'prng', 'ascii'])
        if kind == 'runs':
            seg = _gen_runs(rng, seg_len)
        elif kind == 'periodic':
            seg = _gen_periodic(rng, seg_len)
        elif kind == 'ramp2':
            seg = _gen_ramps(rng, seg_len, 2)
        elif kind == 'ramp4':
            seg = _gen_ramps(rng, seg_len, 4)
        elif kind == 'ascii':
            seg = _gen_ascii(rng, seg_len)
        else:
            seg = _gen_prng(rng, seg_len)
        pieces.append(seg)
        remaining -= seg_len
    return b"".join(pieces)[:target_len]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Candidate sizes, weighted towards useful caps in stubs (<=1024)
    sizes = [0, 1, 2, 3, 4, 7, 8, 15, 16, 31, 32, 63, 64, 127, 128, 255, 256, 511, 512, 767, 768, 1000, 1024]
    weights = [1, 2, 2, 2, 2, 2, 3, 3, 3, 3, 3, 4, 4, 5, 5, 5, 5, 4, 4, 3, 3, 3, 5]
    total = sum(weights)
    pick = rng.randrange(total)
    cum = 0
    target_len = sizes[-1]
    for s, w in zip(sizes, weights):
        cum += w
        if pick < cum:
            target_len = s
            break

    # Jitter size slightly but keep within [0,1024]
    if target_len > 0 and rng.random() < 0.4:
        jitter = rng.randint(-31, 31)
        target_len = max(1, min(1024, target_len + jitter))

    strategy = rng.choice(['runs', 'periodic', 'ramp2', 'ramp4', 'ramp8', 'prng', 'ascii', 'mix'])

    if target_len == 0:
        return b""

    if strategy == 'runs':
        data = _gen_runs(rng, target_len)
    elif strategy == 'periodic':
        data = _gen_periodic(rng, target_len)
    elif strategy == 'ramp2':
        data = _gen_ramps(rng, target_len, 2)
    elif strategy == 'ramp4':
        data = _gen_ramps(rng, target_len, 4)
    elif strategy == 'ramp8':
        data = _gen_ramps(rng, target_len, 8)
    elif strategy == 'ascii':
        data = _gen_ascii(rng, target_len)
    elif strategy == 'mix':
        data = _compose_segments(rng, target_len)
    else:
        data = _gen_prng(rng, target_len)

    # Occasionally prefix with a short ASCII header-like token
    if target_len >= 8 and rng.random() < 0.25:
        prefix = rng.choice([
            b"name:", b"path:", b"meta:", b"dtype:", b"np:", b"url:", b"file:"
        ])
        tok_len = rng.randint(1, min(24, max(1, target_len - len(prefix) - 1)))
        token = _gen_ascii(rng, tok_len)
        hdr = prefix + token + b"\n"
        if len(hdr) < len(data):
            body = data[: len(data) - len(hdr)]
        else:
            body = b""
        data = (hdr + body)[:target_len]

    return data

import random
import string
from typing import List

# Generates bytes containing multiple null-terminated C strings for use by fuzz stubs
# that expect free-form text strings and filenames. Seeded randomness, <= 4096 bytes.

MAX_TOTAL = 4096

KNOWN_COMPRESSORS = [
    b"blosclz", b"lz4", b"lz4hc", b"zlib", b"zstd", b"snappy", b"deflate", b"brotli"
]

EDGE_NAMES = [
    b"",  # empty
    b"0", b"1", b"-1", b"9",
    b"default", b"noop", b"custom", b"test", b"io", b"stdio", b"mmap",
    b"NaN", b"ZERO", b"UNINIT",
    # Some UTF-8 sequences
    "compresor-\x1f".encode("utf-8", "ignore"),
    "nombre-\x03beta".encode("utf-8", "ignore"),
    "过滤器".encode("utf-8"),
    b"a" * 31,
    b"b" * 32,
    b"c" * 64,
    b"d" * 128,
    b"e" * 256,
]

FILE_EXTS = [b".bl2", b".b2nd", b".frame", b".bin", b".dat", b".tmp"]
FILE_MODES = [b"rb", b"wb+", b"r+b", b"w+b", b"ab", b"a+b"]

ASCII_SAFE = (string.ascii_letters + string.digits + "-_.,+@#").encode()


def _rand_ascii(rng: random.Random, min_len: int, max_len: int) -> bytes:
    n = rng.randint(min_len, max_len)
    # Choose bytes from ASCII_SAFE
    return bytes([rng.choice(ASCII_SAFE) for _ in range(n)])


def _rand_bytes(rng: random.Random, min_len: int, max_len: int) -> bytes:
    n = rng.randint(min_len, max_len)
    data = bytearray()
    for _ in range(n):
        if rng.random() < 0.85:
            data.append(rng.randint(32, 126))  # printable
        else:
            data.append(rng.choice([9, 10, 13, 1, 2, 3, 31, 127]))
    # Avoid embedded NULs to keep each token a single C string
    return bytes(b if b != 0 else 32 for b in data)


def _bounded(rng: random.Random, data: bytes, maxlen: int) -> bytes:
    if len(data) <= maxlen:
        return data
    start = 0
    if rng.random() < 0.3 and maxlen > 0:
        start = len(data) - maxlen
    return data[start:start + maxlen]


def _make_filename(rng: random.Random) -> bytes:
    parts: List[bytes] = []
    depth = rng.randint(0, 3)
    for _ in range(depth):
        seg = _rand_ascii(rng, 1, rng.randint(3, 12))
        parts.append(seg)
    base = _rand_ascii(rng, 3, rng.randint(5, 16))
    ext = rng.choice(FILE_EXTS)
    path = b"/".join(parts + [base + ext]) if parts else (base + ext)
    if rng.random() < 0.2:
        path = b"/" + path
    return _bounded(rng, path, 200)


def _name_pool(rng: random.Random) -> List[bytes]:
    pool: List[bytes] = []
    pool.extend(KNOWN_COMPRESSORS)
    pool.extend(EDGE_NAMES)
    for cap in (8, 16, 31, 32, 48, 64, 96, 128, 200, 256):
        for _ in range(rng.randint(1, 3)):
            pool.append(_bounded(rng, _rand_ascii(rng, 1, cap), cap))
    for _ in range(6):
        pool.append(_bounded(rng, _rand_bytes(rng, 1, 256), 256))
    return pool


def _emit_cstr(buf: bytearray, s: bytes):
    buf += s
    buf.append(0)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    buf = bytearray()

    # 1) Compressor-related names
    comp_order = list(KNOWN_COMPRESSORS) + [b"unknown", b"", b"zst", b"lz4hc", b"zstd"]
    rng.shuffle(comp_order)
    for s in comp_order[:6]:
        _emit_cstr(buf, s)

    # 2) General short names (<=32)
    names = _name_pool(rng)
    rng.shuffle(names)
    for s in names[:12]:
        _emit_cstr(buf, _bounded(rng, s, 32))

    # 3) VLMeta names (<=31) and contents (<=256)
    for _ in range(6):
        name = _bounded(rng, rng.choice(names), 31)
        content = _bounded(rng, rng.choice(names), 256)
        if len(name) == 0:
            name = b"a"
        if len(content) == 0:
            content = b"x"
        _emit_cstr(buf, name)
        _emit_cstr(buf, content)

    # 4) Filenames
    for _ in range(6):
        _emit_cstr(buf, _make_filename(rng))

    # 5) Modes for stdio_open
    for m in FILE_MODES:
        _emit_cstr(buf, m)

    # 6) Extra raw payloads
    for _ in range(8):
        _emit_cstr(buf, _bounded(rng, _rand_bytes(rng, 1, 128), 256))

    if len(buf) > MAX_TOTAL:
        buf = buf[:MAX_TOTAL]
        if buf and buf[-1] != 0:
            buf[-1] = 0

    return bytes(buf)
